using Half = std::ratio<1, 2>;
using Third = std::ratio<1, 3>;
using TwoFifths = std::ratio<4, 10>; // Normalized to 2/5

// Compile-time Multiplication: (1/2) * (1/3) = 1/6
using Product = std::ratio_multiply<Half, Third>;
static_assert(Product::num == 1 && Product::den == 6);

// Compile-time Addition: (1/3) + (2/5) = 11/15
using Sum = std::ratio_add<Third, TwoFifths>;
static_assert(Sum::num == 11 && Sum::den == 15);

// Compile-time Subtraction: (1/2) - (1/3) = 1/6
using Difference = std::ratio_subtract<Half, Third>;
static_assert(Difference::num == 1 && Difference::den == 6);

// Compile-time Comparison (using value member)
constexpr bool is_smaller = std::ratio_less<Third, Half>::value;
static_assert(is_smaller);
